      'category' => 'foundfootage',
      'tag' => '#FoundFootage',
      'description' => 'Quatro episódios que contam a história de um grupo de adolescentes que dirige à noite por uma estrada privada, entra em um loop temporal infinito e é atormentado por um homem mascarado. O criador Stephen Chamberlain tinha apenas 17 anos quando publicou o primeiro episódio. Os intervalos longos entre os episódios, de 2009 a 2012, intensificaram a obsessão da comunidade online da época.',
