      'rating' => 'TV-14 (terror cósmico, imagens perturbadoras)',
      'original_title' => 'Gemini Home Entertainment',
      'synopsis' => 'Estruturada como uma coleção de fitas VHS de uma empresa fictícia de mídia doméstica. Através de documentários sobre a natureza, desenhos animados infantis e vídeos corporativos, a série tece uma narrativa de terror cósmico em larga escala. A trama revela gradualmente uma invasão alienígena: criaturas chamadas Woodcrawlers e uma entidade cósmica conhecida como Iris estão transformando a Terra.',
      'story' => 'A série começa em 2019 com "World\'s Weirdest Animals", que parece um documentário animal inofensivo, mas rapidamente se torna sombrio. Episódios como "Storm Safety Tips" e "Our Solar System" expandem o mundo, introduzindo novas entidades. A trama central envolve a nave "Crusader 5" que chega a Iris, um corpo celeste na posição de Netuno. A nave entra em seu interior e descobre que Iris é senciente e criou os "Gardeners", "Roots" e "Woodcrawlers". Ao se aproximar do "núcleo de consciência" de Iris, a nave é rapidamente devolvida à Terra. A série também apresenta a "Deep Root Disease", uma infecção que manipula tecido vivo e transforma humanos em estruturas semelhantes a raízes. O horror vem da escala cósmica da ameaça e da forma como ela se infiltra na vida cotidiana através de mídias aparentemente inocentes.',
