    11 => 
    array (
      'id' => 12,
      'slug' => 'themanact',
      'title' => 'The Mandela Catalogue',
      'category' => 'bcasthijacks',
      'tag' => '#BroadcastHijacks',
      'description' => 'A história se passa no fictício Condado de Mandela, Wisconsin, onde uma raça de demônios sósias chamados Alternates, ou Substitutos, está se espalhando. Eles imitam a aparência humana, torturam suas vítimas psicologicamente e depois as substituem. A narrativa é montada através de transmissões de emergência, anúncios de serviço público e fragmentos de vídeos encontrados.',
