      'category' => 'foundfootage',
      'tag' => '#FoundFootage',
      'description' => 'Websérie que segue Jay, um estudante que tenta descobrir o que aconteceu com o projeto de filme inacabado de seu amigo Alex. Enquanto assiste às fitas, Jay percebe que ele e Alex estão sendo perseguidos por uma entidade conhecida como The Operator, o Slender Man. A série é considerada um dos precursores do analog horror, estabelecendo o formato de filmagem encontrada de baixa qualidade e narrativa fragmentada que depende da participação dos fãs.',
      'warning' => 'Conteúdo sensível: perseguição, violência, morte e horror psicológico.',
